pub fn longest<'a>(values: &'a [&'a str]) -> Option<&'a str> {
    values.iter().copied().max_by_key(|value| value.len())
}

use std::collections::HashSet;

pub fn dedup_ordered(values: Vec<i32>) -> Vec<i32> {
    let mut seen = HashSet::new();
    values.into_iter().filter(|v| seen.insert(*v)).collect()
}

use std::collections::HashMap;

pub fn word_frequencies(text: &str) -> HashMap<&str, usize> {
    let mut freq = HashMap::new();
    for word in text.split_whitespace() {
        *freq.entry(word).or_insert(0) += 1;
    }
    freq
}

pub enum Outcome<T, E> {
    Ok(T),
    Err(E),
}

impl<T, E> Outcome<T, E> {
    pub fn map<U, F: FnOnce(T) -> U>(self, f: F) -> Outcome<U, E> {
        match self {
            Outcome::Ok(v)  => Outcome::Ok(f(v)),
            Outcome::Err(e) => Outcome::Err(e),
        }
    }
}

pub fn chunks<T>(slice: &[T], size: usize) -> Vec<&[T]> {
    slice.chunks(size).collect()
}

use std::ops::Add;

#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Vec2 { pub x: f64, pub y: f64 }

impl Add for Vec2 {
    type Output = Vec2;
    fn add(self, rhs: Vec2) -> Vec2 {
        Vec2 { x: self.x + rhs.x, y: self.y + rhs.y }
    }
}

